import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AwsService } from 'src/app/services/emis/aws.service';
@Component({
  selector: 'app-statistic',
  templateUrl: './statistic.page.html',
  styleUrls: ['./statistic.page.scss'],
})
export class StatisticPage implements OnInit {
  schoolCategory: any;
  schoolData: any;
  routeData: any;
  Id: any;
  Menu: any;

  constructor(private router: Router,private awsService: AwsService,
    private route: ActivatedRoute) {
  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.Id = this.routeData.queryParams.Id;
    this.Menu = this.routeData.queryParams.Menu;
     this.getStatData();
  }

  getStatData() {
    this.awsService.getStatisticData(this.Id).subscribe((res) => {
      if (res) {
        this.schoolData = res[0];
        this.schoolCategory = res[1];
      }
    });
  }

  goToBack() {
    this.router.navigate(['/tabs/home']);
  }
  
}